fn create_row(n: u8) -> Vec<u8> {
    (0..n).collect() // Create a vector from the range 0 to n-1
}

fn indices(n: u8) -> Vec<Vec<u8>> {
    vec![create_row(n)] // Wrap the result of create_row in a vector
}

// Example usage
fn main() {
    let n = 5;
    let row = create_row(n);
    let grid = indices(n);
    
    println!("{:?}", row); // Output: [0, 1, 2, 3, 4]
    println!("{:?}", grid); // Output: [[0, 1, 2, 3, 4]]
}